import React, { useMemo } from "react";
import {
  AbsoluteFill,
  interpolate,
  useCurrentFrame,
  useVideoConfig,
  random,
} from '../remotionShim';
{/* Start Google Fonts Loader */}
const useFontLoader = (fonts: string[]) => {
  const stableFonts = React.useMemo(() => {
    const unique = [...new Set(fonts.map((f) => f.trim()))].sort();
    return unique;
  }, [fonts.join("|")]);

  React.useEffect(() => {
    const unloaded = stableFonts.filter(
      (font) =>
        !document.querySelector(
          `link[href*="${font.replace(/\s+/g, "+")}"]`
        )
    );

    if (unloaded.length === 0) return;

    const url = `https://fonts.googleapis.com/css2?${unloaded
      .map((font) => `family=${font.replace(/\s+/g, "+")}:wght@400;600;700`)
      .join("&")}&display=swap`;

    const link = document.createElement("link");
    link.rel = "stylesheet";
    link.href = url;

    document.head.appendChild(link);
  }, [stableFonts]);
};
{/* End Google Fonts Loader */}



export type GalaxySpinProps = Record<string, any>;

const SpinningGlobe = ({
  color,
  size,
  rotation,
}: {
  color: string;
  size: number;
  rotation: number;
}) => {
  return (
    <div
      style={{
        width: size,
        height: size,
        position: "relative",
        perspective: size * 4,
        transformStyle: "preserve-3d",
      }}
    >
      {/* Glow */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          borderRadius: "50%",
          boxShadow: `0 0 ${size * 0.4}px ${color}`,
          opacity: 0.3,
        }}
      />
      
      {/* Outer Ring */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          border: `2px solid ${color}`,
          borderRadius: "50%",
          opacity: 0.8,
        }}
      />

      {/* Rotating Longitude Lines */}
      {[0, 60, 120].map((deg) => (
        <div
          key={deg}
          style={{
            position: "absolute",
            inset: 0,
            border: `1px solid ${color}`,
            borderRadius: "50%",
            transform: `rotateY(${rotation + deg}deg)`,
            opacity: 0.6,
          }}
        />
      ))}

      {/* Equator (Latitude) */}
      <div
        style={{
          position: "absolute",
          inset: 0,
          border: `1px solid ${color}`,
          borderRadius: "50%",
          transform: `rotateX(80deg)`,
          opacity: 0.5,
        }}
      />
    </div>
  );
};

const GalaxySpin: React.FC<GalaxySpinProps> = ({
  backgroundColor = "#000000",
  transparentBackground = false,
  durationInSeconds = 10,
  starColor = "#a0c4ff",
  coreColor = "#e63946",
  textColor = "#ffffff",
  galaxySize = 1,
  rotationSpeed = 1,
  textScale = 1,
}) => {
  useFontLoader(["Cinzel"]);

  const frame = useCurrentFrame();
  const { width, height, fps } = useVideoConfig();

  // Color logic
  const finalBgColor = transparentBackground ? "transparent" : backgroundColor;

  // Generate Background Particles
  const particles = useMemo(() => {
    const bgArray = [];
    const count = 60;
    for (let i = 0; i < count; i++) {
      const seed = `bg-particle-${i}`;
      const x = random(seed + "x") * width;
      const y = random(seed + "y") * height;
      const size = random(seed + "s") * 3 + 1;
      const opacity = random(seed + "o") * 0.4 + 0.1;
      bgArray.push({ x, y, size, opacity });
    }
    return bgArray;
  }, [width, height]);

  // Dimensions
  const globeSize = galaxySize * 180;
  
  // Globe Animation
  const totalRotation = frame * rotationSpeed * 1.5;

  // Text Logic
  const textSegments = [
    "WHAT BENEFIT DO YOU GET FROM STRESSING IF IT WILL WORK OUT",
    "RATHER THAN ASKING IF YOU'RE ON THE CORRECT PATH",
    "WE WERE ALL CALLED TO OUR OWN PATH FIND OUT YOURS",
  ];

  const totalFrames = durationInSeconds * fps;
  const segmentDuration = totalFrames / textSegments.length;
  const currentSegmentIndex = Math.min(
    Math.floor(frame / segmentDuration),
    textSegments.length - 1
  );
  
  const currentText = textSegments[currentSegmentIndex];
  
  // Calculate local time within the segment for fade effects
  const segmentStartFrame = currentSegmentIndex * segmentDuration;
  const timeInSegment = frame - segmentStartFrame;
  
  const fadeDuration = 15; // Frames
  
  const opacityIn = interpolate(timeInSegment, [0, fadeDuration], [0, 1], {
    extrapolateRight: "clamp",
  });
  
  const opacityOut = interpolate(
    timeInSegment,
    [segmentDuration - fadeDuration, segmentDuration],
    [1, 0],
    {
      extrapolateRight: "clamp",
      extrapolateLeft: "clamp",
    }
  );

  // Combine opacities (fade in at start, fade out at end)
  const textOpacity = Math.min(opacityIn, opacityOut);
  
  // Slight upward float effect for text
  const textTranslateY = interpolate(
    timeInSegment,
    [0, segmentDuration],
    [20, -20],
    { extrapolateRight: "clamp" }
  );

  // Blur effect for text transitions
  const textBlur = interpolate(
    textOpacity,
    [0, 1],
    [10, 0], 
    { extrapolateRight: "clamp" }
  );

  return (
    <AbsoluteFill
      style={{
        backgroundColor: finalBgColor,
        fontFamily: "Cinzel",
        overflow: "hidden",
      }}
    >
      {/* Background Particles */}
      <AbsoluteFill>
        {particles.map((p, i) => (
          <div
            key={i}
            style={{
              position: "absolute",
              left: p.x,
              top: p.y,
              width: p.size,
              height: p.size,
              backgroundColor: starColor,
              opacity: p.opacity,
              borderRadius: "50%",
              boxShadow: `0 0 ${p.size * 2}px ${starColor}`,
            }}
          />
        ))}
      </AbsoluteFill>

      {/* Content Container */}
      <AbsoluteFill
        style={{
          display: "flex",
          flexDirection: "column",
          justifyContent: "center",
          alignItems: "center",
          gap: 50 * galaxySize,
        }}
      >
        {/* Text Overlay */}
        <div
          style={{
            textAlign: "center",
            color: textColor,
            opacity: textOpacity,
            transform: `translateY(${textTranslateY}px)`,
            filter: `blur(${textBlur}px)`,
            maxWidth: width * 0.8,
            fontSize: 40 * textScale,
            fontWeight: 700,
            textShadow: `0 4px 20px rgba(0,0,0,0.5)`,
            lineHeight: 1.4,
            zIndex: 20,
            minHeight: 120 * textScale, // Reserve space to prevent jumping
            display: "flex",
            alignItems: "center",
            justifyContent: "center",
          }}
        >
          {currentText}
        </div>

        {/* Spinning Globe (Below Text) */}
        <div
          style={{
            width: globeSize,
            height: globeSize,
            display: "flex",
            justifyContent: "center",
            alignItems: "center",
            transform: "rotateZ(15deg)", // Tilt the axis slightly
            transition: "none",
          }}
        >
          <SpinningGlobe 
            color={coreColor} 
            size={globeSize} 
            rotation={totalRotation} 
          />
        </div>
      </AbsoluteFill>
    </AbsoluteFill>
  );
};

export default GalaxySpin;